#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int N = 7002;

int n;
ll a[N], b[N];
bool chk[N];
int cnt[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    for (int i = 1; i <= n; ++i) cin >> b[i];

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (a[i] > (a[i] & a[j])) ++cnt[i];
        }
    }

    int cur = n;
    while (true) {
        vector<int> removed;

        for (int i = 1; i <= n; ++i) {
            if (!chk[i] && cnt[i] == cur - 1) {
                removed.push_back(i);
            }
        }

        if (removed.empty()) break;

        for (int u : removed) {
            chk[u] = true;
            --cur;
        }

        for (int i = 1; i <= n; ++i) {
            if (!chk[i]) {
                for (int u : removed) {
                    if (a[i] > (a[i] & a[u])) --cnt[i];
                }
            }
        }
    }

    ll ans = 0;
    for (int i = 1; i <= n; ++i) {
        if (!chk[i]) ans += b[i];
    }

    cout << ans << '\n';
    return 0;
}

