#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int N = 7002;

int n, deg[N];
ll a[N], b[N];
bool removed[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    for (int i = 1; i <= n; ++i) cin >> b[i];

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (a[i] > (a[i] & a[j])) ++deg[i];
        }
    }

    int remaining = n;
    while (true) {
        vector<int> eraseList;

        for (int i = 1; i <= n; ++i) {
            if (!removed[i] && deg[i] == remaining - 1)
                eraseList.push_back(i);
        }

        if (eraseList.empty()) break;

        for (int u : eraseList) removed[u] = true;
        remaining -= static_cast<int>(eraseList.size());

        for (int i = 1; i <= n; ++i) {
            if (removed[i]) continue;
            for (int u : eraseList) {
                if (a[i] > (a[i] & a[u])) --deg[i];
            }
        }
    }

    ll answer = 0;
    for (int i = 1; i <= n; ++i) {
        if (!removed[i]) answer += b[i];
    }

    cout << answer << '\n';
    return 0;
}

