#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> a(n), b(n);
    unordered_map<ll, int> frequency;

    for (ll &x : a) {
        cin >> x;
        ++frequency[x];
    }
    for (ll &x : b) cin >> x;

    vector<ll> duplicated;
    duplicated.reserve(frequency.size());
    for (const auto &[value, count] : frequency) {
        if (count > 1) duplicated.push_back(value);
    }

    ll answer = 0;
    for (int i = 0; i < n; ++i) {
        for (ll value : duplicated) {
            if ((a[i] & value) == a[i]) {
                answer += b[i];
                break;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

